/* 需要彻底复位 EXTI 时（调试用） */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);
EXTI_DeInit();

/* 复位后必须重新做引脚映射，否则中断线接不到任何 GPIO */
GPIO_EXTILineConfig(GPIO_PortSourceGPIOB, GPIO_PinSource0);

EXTI_InitTypeDef EXTI_InitStructure;
GPIO_InitTypeDef GPIO_InitStructure;
NVIC_InitTypeDef NVIC_InitStructure;

/* 1. 必须开 AFIO 时钟（很多库的 GPIO 例子没开，这里的 EXTI/重映射都要） */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB | RCC_APB2Periph_AFIO, ENABLE);

/* 2. 引脚配成上拉输入（按键按下接地，用 EXTI_Trigger_Falling） */
GPIO_InitStructure.GPIO_Pin  = GPIO_Pin_0;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;
GPIO_Init(GPIOB, &GPIO_InitStructure);

/* 3. 把 PB0 映射到 EXTI_Line0 */
GPIO_EXTILineConfig(GPIO_PortSourceGPIOB, GPIO_PinSource0);

/* 4. 配中断线：下降沿触发，走中断模式 */
EXTI_InitStructure.EXTI_Line    = EXTI_Line0;
EXTI_InitStructure.EXTI_Mode    = EXTI_Mode_Interrupt;
EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Falling;
EXTI_InitStructure.EXTI_LineCmd = ENABLE;
EXTI_Init(&EXTI_InitStructure);

/* 5. NVIC 使能——不做这步中断永远不来 */
NVIC_InitStructure.NVIC_IRQChannel = EXTI0_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x02;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x02;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

/* 6. 中断服务函数：先判标志，再清标志，最后干活 */
void EXTI0_IRQHandler(void)
{
  if (EXTI_GetITStatus(EXTI_Line0) != RESET)
  {
    EXTI_ClearITPendingBit(EXTI_Line0);   /* 必须在处理前清，否则会重复进 */
    /* 用户代码 */
  }
}

EXTI_InitTypeDef EXTI_InitStructure;

EXTI_StructInit(&EXTI_InitStructure);      /* 先给默认值 */
EXTI_InitStructure.EXTI_Line    = EXTI_Line13;
EXTI_InitStructure.EXTI_Mode    = EXTI_Mode_Interrupt;
EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Falling;
EXTI_InitStructure.EXTI_LineCmd = ENABLE;  /* 默认是 DISABLE，别忘 */
EXTI_Init(&EXTI_InitStructure);

/* 上电自检：手动触发一次 EXTI_Line0，确认中断链路通了 */
EXTI_GenerateSWInterrupt(EXTI_Line0);

/* 若中断服务函数里的计数器没有自增，问题在 NVIC/EXTI_Init，而不在外部信号 */

/* 轮询方式等待 PB0 上的下降沿，不使用中断 */
if (EXTI_GetFlagStatus(EXTI_Line0) != RESET)
{
  EXTI_ClearFlag(EXTI_Line0);   /* 轮询也必须清标志 */
  /* 用户代码 */
}

/* 进中断或轮询到标志后立刻清，避免重复触发 */
EXTI_ClearFlag(EXTI_Line0);

/* 同时清 Line13 与 Line14（可用于 EXTI15_10_IRQHandler 里） */
EXTI_ClearFlag(EXTI_Line13 | EXTI_Line14);

/* EXTI9_5 上挂了 Line5~Line9 五根线，必须逐条判断 */
void EXTI9_5_IRQHandler(void)
{
  if (EXTI_GetITStatus(EXTI_Line5) != RESET)
  {
    EXTI_ClearITPendingBit(EXTI_Line5);
    /* 处理 PA5/PB5/PC5 上的事件 */
  }
  if (EXTI_GetITStatus(EXTI_Line6) != RESET)
  {
    EXTI_ClearITPendingBit(EXTI_Line6);
    /* 处理 */
  }
}

void EXTI15_10_IRQHandler(void)
{
  if (EXTI_GetITStatus(EXTI_Line13) != RESET)
  {
    EXTI_ClearITPendingBit(EXTI_Line13);   /* 先清，再干活 */
    /* 用户代码：例如翻转 LED */
  }
}
